{"id": "v19/support/self_protection", "version": 1, "symbol": "self_protection", "kind": "constructor", "status": "Accepted", "signature": "TERM self_protection(actor: STRING / TERM, domain: STRING, strategy?: STRING / TERM) -> TERM", "definition": "Constructs a descriptive term representing an actor's self-protection practice, emotional boundary guarding, or coping strategy within a domain.", "not": "safe (a physical security container) or prohibited (a deontic rule)", "aliases": ["guarding heart", "emotional boundaries", "protect oneself", "coping strategy"], "shared_rules": ["v19/rule/support-primitives-general"]}
